def job_scheduling(deadlines: list[int], profits: list[int]) -> int:
    jobs = sorted(zip(deadlines, profits), key=lambda x: x[1], reverse=True)
    max_deadline = max(deadlines) if deadlines else 0
    slots = [-1] * (max_deadline + 1)
    total_profit = 0
    for d, p in jobs:
        for slot in range(d, 0, -1):
            if slots[slot] == -1:
                slots[slot] = p
                total_profit += p
                break
    return total_profit
